// Extract all tool calls from VAPI payload.
// Maps each tool call to its own item for independent Switch routing.
try {
  var input = $input.first().json;
  var msg = input.body && input.body.message ? input.body.message
             : (input.message ? input.message : input);

  // Phone: 3 possible paths per VAPI spec
  var phone = (msg.call && msg.call.customer && msg.call.customer.number)
             || (msg.call && msg.call.customer && msg.call.customer.phoneNumber)
             || (msg.customer && msg.customer.number)
             || '';

  // Call direction for Booked By attribution (voice-outbound vs voice-inbound)
  var callDirection = 'voice-outbound';
  if (msg.call) {
    var callType = msg.call.type || '';
    var callDir = msg.call.direction || '';
    if (callType === 'inboundPhoneCall' || callDir === 'inbound') {
      callDirection = 'voice-inbound';
    }
  }

  var callId = (msg.call && msg.call.id) || '';
  var toolCallList = msg.toolCallList || [];

  if (!toolCallList.length) {
    return [{ json: { toolCallId: 'unknown', toolName: 'unknown', args: {}, phone: phone, callId: callId, callDirection: callDirection } }];
  }

  // One n8n item per tool call
  return toolCallList.map(function(tc) {
    var args = {};
    try { args = JSON.parse(tc.function.arguments || '{}'); } catch(e) { args = {}; }
    return { json: { toolCallId: tc.id, toolName: tc.function.name, args: args, phone: phone, callId: callId, callDirection: callDirection } };
  });
} catch (e) {
  return [{ json: { toolCallId: 'unknown', toolName: 'unknown', args: {}, phone: '', callId: '', callDirection: 'voice-outbound', error: 'Failed to parse VAPI payload: ' + e.message } }];
}

try {
  // B9 sibling: this used the Sheets node's EXACT string match on Phone, so a stored number
  // missing its '+' or carrying a space made a known customer look like a stranger mid-call.
  // Read the tab and match on digits (last 9, so a differing country code still matches).
  var src = $('Extract Tool Calls').first().json;
  var wanted = String((src.args && src.args.phone) || src.phone || '').replace(/[^0-9]/g, '');
  var rows = $input.all();
  var row = null;
  if (wanted) {
    for (var i = 0; i < rows.length; i++) {
      var r = rows[i].json || {};
      var d = String(r['Phone'] || '').replace(/[^0-9]/g, '');
      if (!d) { continue; }
      if (d === wanted || (d.slice(-9).length === 9 && d.slice(-9) === wanted.slice(-9))) { row = r; break; }
    }
  }
  if (!row || !row['Phone']) {
    return [{ json: { toolCallId: src.toolCallId, result: 'No prior record found for this caller. This appears to be a new contact.' } }];
  }
  var name = row['Name'] || 'Unknown';
  var status = row['Status'] || 'new';
  var serviceInterest = row['Service Interest'] || 'Not specified';
  var leadSource = row['Lead Source'] || 'Not specified';
  var lastChannel = row['Last Channel'] || 'none';
  var callCount = row['Call Count'] || '0';
  var lastContact = row['Last Contact'] || 'Never';
  var lastOutcome = row['Last Outcome'] || 'None';
  var upcomingAppt = row['Upcoming Appointment'] || 'None';
  return [{ json: { toolCallId: src.toolCallId, result: 'Caller found. Name: ' + name + '. Status: ' + status + '. Service interest: ' + serviceInterest + '. Lead source: ' + leadSource + '. Last channel: ' + lastChannel + '. Call count: ' + callCount + '. Last contact: ' + lastContact + '. Last outcome: ' + lastOutcome + '. Upcoming appointment: ' + upcomingAppt + '.' } }];
} catch (e) {
  var fid = '';
  try { fid = $('Extract Tool Calls').first().json.toolCallId; } catch(x) {}
  return [{ json: { toolCallId: fid || 'unknown', result: 'I could not look up your record just then. Could you confirm your name for me?' } }];
}

try {
  var item = $input.first().json;
  var toolCallId = item.toolCallId;
  var dateInput = (item.args && item.args.date ? item.args.date : 'tomorrow').toLowerCase().trim();

  function parseTargetDate(input) {
    var today = new Date();
    today.setHours(0,0,0,0);
    if (input === 'today') return new Date(today);
    if (input === 'tomorrow') { var d = new Date(today); d.setDate(d.getDate()+1); return d; }
    // D3 BUG-R31: an explicit day+month must beat the weekday name.
    var monthWords = ['january','february','march','april','may','june','july','august','september','october','november','december'];
    var mIdx = -1;
    for (var mw = 0; mw < monthWords.length; mw++) {
      if (input.indexOf(monthWords[mw]) !== -1) { mIdx = mw; break; }
    }
    var dayNumMatch = input.match(/(\d{1,2})\s*(?:st|nd|rd|th)?/);
    var dayNum = dayNumMatch ? parseInt(dayNumMatch[1], 10) : 0;
    if (mIdx !== -1 && dayNum >= 1 && dayNum <= 31) {
      var cand = new Date(today.getFullYear(), mIdx, dayNum);
      cand.setHours(0,0,0,0);
      if (cand.getTime() < today.getTime()) { cand.setFullYear(today.getFullYear() + 1); }
      return cand;
    }

    var dayMap = {sunday:0,monday:1,tuesday:2,wednesday:3,thursday:4,friday:5,saturday:6};
    var keys = Object.keys(dayMap);
    for (var i = 0; i < keys.length; i++) {
      if (input.indexOf(keys[i]) >= 0) {
        var d = new Date(today);
        var diff = dayMap[keys[i]] - d.getDay();
        if (diff <= 0) diff += 7;
        d.setDate(d.getDate() + diff);
        return d;
      }
    }
    if (input.indexOf('next week') >= 0) { var d = new Date(today); d.setDate(d.getDate()+7); return d; }
    // D3 BUG-R32: V8 defaults a yearless string to the year 2001.
    var parsed = new Date(input);
    if (!isNaN(parsed.getTime())) {
      parsed.setHours(0,0,0,0);
      if (parsed.getTime() < today.getTime()) { parsed.setFullYear(today.getFullYear()); }
      if (parsed.getTime() < today.getTime()) { parsed.setFullYear(today.getFullYear() + 1); }
      return parsed;
    }
    var d = new Date(today); d.setDate(d.getDate()+1); return d;
  }

  var targetDate = parseTargetDate(dateInput);
  // D2 F1: the search window is London wall-clock 8am–6pm, built explicitly in UTC so it
  // does not shift with the server's timezone.
  var bstMonth = targetDate.getMonth() + 1;
  var utcOffset = (bstMonth >= 3 && bstMonth <= 10) ? 1 : 0;
  var timeMin = new Date(Date.UTC(targetDate.getFullYear(), targetDate.getMonth(), targetDate.getDate(), 8 - utcOffset, 0, 0));
  var timeMax = new Date(Date.UTC(targetDate.getFullYear(), targetDate.getMonth(), targetDate.getDate(), 18 - utcOffset, 0, 0));
  var friendlyDate = targetDate.toLocaleDateString('en-GB', { weekday: 'long', day: 'numeric', month: 'long' });

  return [{ json: { toolCallId: toolCallId, timeMin: timeMin.toISOString(), timeMax: timeMax.toISOString(), utcOffset: utcOffset, friendlyDate: friendlyDate, dateInput: dateInput } }];
} catch (e) {
  var fallbackId = '';
  try { fallbackId = $input.first().json.toolCallId; } catch(x) {}
  return [{ json: { toolCallId: fallbackId || 'unknown', result: 'I had trouble parsing that date. Could you tell me which day you prefer?' } }];
}

try {
  var parseData = $('Parse Availability Date').first().json;
  var toolCallId = parseData.toolCallId;
  var friendlyDate = parseData.friendlyDate;
  var timeMin = new Date(parseData.timeMin);
  var timeMax = new Date(parseData.timeMax);

  // D3 BUG-R4: Get Calendar Events runs with onError=continueRegularOutput, so a failed
  // read arrives here as DATA. The filter below would discard the error item, leave
  // bookedSlots empty, and report the whole day as free. Decide explicitly instead.
  var rawEvents = $input.all();
  if (rawEvents.length > 0 && rawEvents[0].json && typeof rawEvents[0].json.error !== 'undefined') {
    return [{ json: { toolCallId: toolCallId, result: 'I could not reach the calendar just then, so I cannot confirm any times. Take the caller details and tell them someone will ring straight back to fix a slot. Do NOT offer any times.' } }];
  }

  var bookedSlots = $input.all()
    .filter(function(i) { return i.json.id && i.json.start; })
    .map(function(i) { return { start: new Date(i.json.start.dateTime || i.json.start.date), end: new Date(i.json.end.dateTime || i.json.end.date) }; })
    .filter(function(s) { return !isNaN(s.start.getTime()); });

  var slots = [];
  var slotStart = new Date(timeMin);
  while (slotStart.getTime() + 2 * 3600000 <= timeMax.getTime()) {
    var slotEnd = new Date(slotStart.getTime() + 2 * 3600000);
    var clash = bookedSlots.some(function(b) { return slotStart < b.end && slotEnd > b.start; });
    if (!clash) {
      // D2 F1: slot boundaries are UTC instants; convert back to the London hour for the
      // spoken label, otherwise every time read to the caller is an hour out in summer.
      var h = (slotStart.getUTCHours() + (parseData.utcOffset || 0)) % 24;
      var ampm = h < 12 ? 'am' : 'pm';
      var h12 = h <= 12 ? h : h - 12;
      slots.push(h12 + ampm);
    }
    slotStart = slotEnd;
  }

  var result;
  if (!slots.length) {
    result = 'No availability on ' + friendlyDate + '. Please try another day. I can check Monday through Friday for you.';
  } else {
    // D3 BUG-R33: offering only three made the assistant treat every other slot as taken,
    // so a caller asking for a free time was told it was unavailable. Give the full list,
    // but tell it to speak only three — nobody wants nine times read down the phone.
    var offered = slots.slice(0, 3);
    result = 'Available on ' + friendlyDate + ': ' + offered.join(', ') + '. Say only those three out loud. Every free slot that day is: ' + slots.join(', ') + ' — if the caller asks for one of those, it IS free, so confirm it instead of offering alternatives.';
  }
  return [{ json: { toolCallId: toolCallId, result: result } }];
} catch (e) {
  var fallbackId = '';
  try { fallbackId = $('Parse Availability Date').first().json.toolCallId; } catch(x) {}
  return [{ json: { toolCallId: fallbackId || 'unknown', result: 'I had trouble checking availability. Could you suggest a day and I will try again?' } }];
}

try {
  var item = $input.first().json;
  var args = item.args || {};
  var toolCallId = item.toolCallId;
  var phone = item.phone;
  var callDirection = item.callDirection || 'voice-outbound';

  function sanitize(str) { return String(str || '').replace(/^[=+\-@]/, '').trim(); }
  var callerName = sanitize(args.callerName || '');
  var callerPhone = args.callerPhone || phone || '';
  var callerEmail = sanitize(args.callerEmail || '');
  var serviceType = sanitize(args.serviceType || 'Solar Survey');
  var address = sanitize(args.address || '');
  var dateStr = args.preferredDate || 'tomorrow';
  var timeStr = (args.preferredTime || '9am').toLowerCase().replace(/\s/g, '');

  if (!callerName || !callerPhone) {
    return [{ json: { toolCallId: toolCallId, result: "I need your name and phone number to book an appointment. Could you confirm those for me?" } }];
  }

  // D3 BUG-R41: an unrecognised time must never silently become some other hour.
  // Returns null on anything we cannot map, and the caller refuses rather than guessing.
  function parseHour(t) {
    if (!/^\d{1,2}(am|pm)$/.test(t)) { return null; }
    var h = parseInt(t, 10);
    if (isNaN(h) || h < 1 || h > 12) { return null; }
    var isPM = t.indexOf('pm') >= 0;
    if (isPM && h !== 12) { return h + 12; }
    if (!isPM && h === 12) { return 0; }
    return h;
  }

  function parseDate(d) {
    var lower = d.toLowerCase().trim();
    var today = new Date(); today.setHours(0,0,0,0);
    if (lower === 'today') return new Date(today);
    if (lower === 'tomorrow') { var r = new Date(today); r.setDate(r.getDate()+1); return r; }
    // D3 BUG-R31: an explicit day+month ("Monday 24 August") must beat the weekday name.
    // Matching 'monday' first made "Monday 24 August" resolve to the NEAREST Monday.
    var monthWords = ['january','february','march','april','may','june','july','august','september','october','november','december'];
    var mIdx = -1;
    for (var mw = 0; mw < monthWords.length; mw++) {
      if (lower.indexOf(monthWords[mw]) !== -1) { mIdx = mw; break; }
    }
    var dayNumMatch = lower.match(/(\d{1,2})\s*(?:st|nd|rd|th)?/);
    var dayNum = dayNumMatch ? parseInt(dayNumMatch[1], 10) : 0;
    if (mIdx !== -1 && dayNum >= 1 && dayNum <= 31) {
      var cand = new Date(today.getFullYear(), mIdx, dayNum);
      cand.setHours(0,0,0,0);
      // A date already past this year means they mean next year.
      if (cand.getTime() < today.getTime()) { cand.setFullYear(today.getFullYear() + 1); }
      return cand;
    }

    var dayMap = {sunday:0,monday:1,tuesday:2,wednesday:3,thursday:4,friday:5,saturday:6};
    var keys = Object.keys(dayMap);
    for (var i = 0; i < keys.length; i++) {
      if (lower.indexOf(keys[i]) >= 0) {
        var r = new Date(today);
        var diff = dayMap[keys[i]] - r.getDay();
        if (diff <= 0) diff += 7;
        r.setDate(r.getDate() + diff);
        return r;
      }
    }
    // D3 BUG-R32: V8's legacy parser defaults a yearless string to the year 2001.
    // Roll forward, and if it is STILL in the past the string was not a usable date.
    var parsed = new Date(d);
    if (!isNaN(parsed.getTime())) {
      parsed.setHours(0,0,0,0);
      if (parsed.getTime() < today.getTime()) { parsed.setFullYear(today.getFullYear()); }
      if (parsed.getTime() < today.getTime()) { parsed.setFullYear(today.getFullYear() + 1); }
      return parsed;
    }
    var r = new Date(today); r.setDate(r.getDate()+1); return r;
  }

  var hour = parseHour(timeStr);
  if (hour === null) {
    return [{ json: { toolCallId: toolCallId, result: "I didn't catch that time. We book on the hour between nine in the morning and five in the afternoon. What time would suit you?" } }];
  }
  var targetDate = parseDate(dateStr);
  // D2 F1: build the instant EXPLICITLY in UTC from the London wall-clock hour, so the
  // result no longer depends on the server's timezone. setHours() used server-local time,
  // which on a UTC host turned a 9am booking into 09:00 UTC = 10am BST — an hour late,
  // every booking, all summer. WF1's Business Hours Check already uses this UTC+offset
  // convention; WF3 now matches it.
  var bstMonth = targetDate.getMonth() + 1;
  var utcOffset = (bstMonth >= 3 && bstMonth <= 10) ? 1 : 0;
  var startUTC = new Date(Date.UTC(targetDate.getFullYear(), targetDate.getMonth(), targetDate.getDate(), hour - utcOffset, 0, 0));
  var endUTC = new Date(startUTC.getTime() + 2 * 3600000);
  var targetDateOut = startUTC;
  var endDate = endUTC;
  var friendlyDate = targetDate.toLocaleDateString('en-GB', { weekday: 'long', day: 'numeric', month: 'long' });
  var friendlyDateTime = friendlyDate + ' at ' + timeStr;

  return [{ json: { toolCallId: toolCallId, callerName: callerName, callerPhone: callerPhone, callerEmail: callerEmail, serviceType: serviceType, address: address, phone: phone, callDirection: callDirection, startISO: targetDateOut.toISOString(), endISO: endDate.toISOString(), friendlyDateTime: friendlyDateTime, friendlyDate: friendlyDate, dateStr: dateStr, timeStr: timeStr } }];
} catch (e) {
  var fallbackId = '';
  try { fallbackId = $input.first().json.toolCallId; } catch(x) {}
  return [{ json: { toolCallId: fallbackId || 'unknown', result: 'I had trouble processing the booking details. Could you repeat your preferred date and time?' } }];
}

try {
  var bookData = $('Parse Booking Request').first().json;
  var calEvent = $('Create Calendar Event').first().json;
  var toolCallId = bookData.toolCallId;
  // The append response tells us whether the CRM row actually landed.
  // Previously this only checked the calendar, so a failed sheet write still said "confirmed"
  // and the booking existed nowhere the rest of the system could see it.
  var appendOk = false;
  try {
    var ap = $input.first().json || {};
    appendOk = !!(ap.updates && ap.updates.updatedRows > 0);
  } catch(x) {}
  var result;
  if (!calEvent.id) {
    result = "I wasn't able to complete the booking right now. Let me take your details and someone will call you back to confirm.";
  } else {
    var ref = calEvent.id.substring(0, 8).toUpperCase();
    result = 'Appointment confirmed. ' + bookData.callerName + ' is booked for a ' + bookData.serviceType + ' on ' + bookData.friendlyDateTime + '. Reference: SOL-' + ref + '. An engineer will call 30 minutes before arrival.';
    if (!appendOk) {
      // Calendar slot is genuinely reserved, so do not tell the caller it failed - but flag it,
      // because with no CRM row there will be no reminders and cancel/reschedule cannot find it.
      result = result + ' (NOTE FOR STAFF: the CRM record did not save - add it manually.)';
    }
  }
  return [{ json: { toolCallId: toolCallId, result: result, crmSaved: appendOk } }];
} catch (e) {
  var fallbackId = '';
  try { fallbackId = $('Parse Booking Request').first().json.toolCallId; } catch(x) { try { fallbackId = $('Extract Tool Calls').first().json.toolCallId; } catch(y) {} }
  return [{ json: { toolCallId: fallbackId || 'unknown', result: 'The booking was processed but I had trouble confirming the details. Someone will follow up with you shortly.' } }];
}

try {
  var item = $input.first().json;
  var args = item.args || {};
  var toolCallId = item.toolCallId;
  var callerPhone = args.callerPhone || item.phone || '';
  var newDate = args.newDate || args.preferredDate || 'tomorrow';
  var newTime = (args.newTime || args.preferredTime || '9am').toLowerCase().replace(/\s/g, '');

  if (!callerPhone) {
    return [{ json: { toolCallId: toolCallId, result: "I need your phone number to find your appointment. Could you provide it?" } }];
  }

  // D3 BUG-R41: never silently resolve an unrecognised time to some other hour.
  function parseHour(t) {
    if (!/^\d{1,2}(am|pm)$/.test(t)) { return null; }
    var h = parseInt(t, 10);
    if (isNaN(h) || h < 1 || h > 12) { return null; }
    var isPM = t.indexOf('pm') >= 0;
    if (isPM && h !== 12) { return h + 12; }
    if (!isPM && h === 12) { return 0; }
    return h;
  }

  function parseDate(d) {
    var lower = d.toLowerCase().trim();
    var today = new Date(); today.setHours(0,0,0,0);
    if (lower === 'tomorrow') { var r = new Date(today); r.setDate(r.getDate()+1); return r; }
    // D3 BUG-R31: an explicit day+month must beat the weekday name.
    var monthWords = ['january','february','march','april','may','june','july','august','september','october','november','december'];
    var mIdx = -1;
    for (var mw = 0; mw < monthWords.length; mw++) {
      if (lower.indexOf(monthWords[mw]) !== -1) { mIdx = mw; break; }
    }
    var dayNumMatch = lower.match(/(\d{1,2})\s*(?:st|nd|rd|th)?/);
    var dayNum = dayNumMatch ? parseInt(dayNumMatch[1], 10) : 0;
    if (mIdx !== -1 && dayNum >= 1 && dayNum <= 31) {
      var cand = new Date(today.getFullYear(), mIdx, dayNum);
      cand.setHours(0,0,0,0);
      if (cand.getTime() < today.getTime()) { cand.setFullYear(today.getFullYear() + 1); }
      return cand;
    }

    var dayMap = {sunday:0,monday:1,tuesday:2,wednesday:3,thursday:4,friday:5,saturday:6};
    var keys = Object.keys(dayMap);
    for (var i = 0; i < keys.length; i++) {
      if (lower.indexOf(keys[i]) >= 0) {
        var r = new Date(today);
        var diff = dayMap[keys[i]] - r.getDay();
        if (diff <= 0) diff += 7;
        r.setDate(r.getDate() + diff);
        return r;
      }
    }
    // D3 BUG-R32: V8 defaults a yearless string to the year 2001.
    var parsed = new Date(d);
    if (!isNaN(parsed.getTime())) {
      parsed.setHours(0,0,0,0);
      if (parsed.getTime() < today.getTime()) { parsed.setFullYear(today.getFullYear()); }
      if (parsed.getTime() < today.getTime()) { parsed.setFullYear(today.getFullYear() + 1); }
      return parsed;
    }
    var r = new Date(today); r.setDate(r.getDate()+1); return r;
  }

  var hour = parseHour(newTime);
  if (hour === null) {
    return [{ json: { toolCallId: toolCallId, result: "I didn't catch that time. We book on the hour between nine in the morning and five in the afternoon. What time would suit you?" } }];
  }
  var targetDate = parseDate(newDate);
  // D2 F1: build the instant EXPLICITLY in UTC from the London wall-clock hour.
  var bstMonth = targetDate.getMonth() + 1;
  var utcOffset = (bstMonth >= 3 && bstMonth <= 10) ? 1 : 0;
  var startUTC = new Date(Date.UTC(targetDate.getFullYear(), targetDate.getMonth(), targetDate.getDate(), hour - utcOffset, 0, 0));
  var endUTC = new Date(startUTC.getTime() + 2 * 3600000);
  var targetDateOut = startUTC;
  var endDate = endUTC;
  var friendlyDateNew = targetDate.toLocaleDateString('en-GB', { weekday: 'long', day: 'numeric', month: 'long' });
  var friendlyNew = friendlyDateNew + ' at ' + newTime;

  return [{ json: { toolCallId: toolCallId, callerPhone: callerPhone, newDate: newDate, newTime: newTime, startISO: targetDateOut.toISOString(), endISO: endDate.toISOString(), friendlyNew: friendlyNew, friendlyDateNew: friendlyDateNew } }];
} catch (e) {
  var fallbackId = '';
  try { fallbackId = $input.first().json.toolCallId; } catch(x) {}
  return [{ json: { toolCallId: fallbackId || 'unknown', result: 'I had trouble processing the reschedule details. Could you tell me the new date and time you prefer?' } }];
}

// Build VAPI tool-calls response.
// CRITICAL: result must be single-line string (no newlines).
var items = $input.all();
var results;
try {
  results = items.map(function(item) {
    var r = (item.json.result || 'Done.').replace(/\n/g, '. ').replace(/\s+/g, ' ').trim();
    return { toolCallId: item.json.toolCallId || 'unknown', result: r };
  });
} catch(e) {
  results = [{ toolCallId: (items[0] && items[0].json && items[0].json.toolCallId) || 'unknown', result: "I'm having a technical issue. Let me take a message and someone will call you back shortly." }];
}
return [{ json: { results: results } }];

var input = $input.first().json;
var toolCallId = input.toolCallId || '';
var args = input.args || {};
var topic = (args.topic || 'about').toLowerCase();

var info = {
  hours: 'Solarify is open Monday to Friday 8am to 6pm, and Saturday 9am to 1pm. We are closed on Sundays and bank holidays. For urgent issues with an existing installation outside these hours, please leave a message and we will call back first thing.',

  services: 'Solarify installs solar PV panels and battery storage systems for UK homeowners. Every installation is MCS-certified. We design, supply, and install everything — including the inverter, mounting system, and cabling. We do not offer heat pumps, insulation, boilers, EV chargers, or any other service. Solar panels and battery storage is our sole focus.',

  pricing: 'Solar panel system prices depend on the size and your roof. As a rough guide: a 3kW system is approximately £5,000 to £7,000, a 4kW system is £6,500 to £8,500, and a 5 to 6kW system is £8,000 to £11,000. Adding battery storage costs an extra £2,000 to £5,500 depending on size and brand. These are indicative ranges only — a firm quote is produced after the free in-home survey, which accounts for your specific roof type, access, and any scaffolding requirements. There is no obligation after the survey.',

  subsidies: 'There are two main financial benefits for UK solar. First, zero percent VAT: since April 2022 there is no VAT on solar panel and battery storage installations — a 20 percent saving versus standard goods. This currently runs to March 2027. Second, the Smart Export Guarantee: once your system is installed and MCS-certified, you apply to your electricity supplier and they pay you for every unit of electricity you export to the grid. Rates currently range from 4 to 15 pence per kilowatt hour depending on your supplier and tariff. There is no national solar installation grant at present. The Boiler Upgrade Scheme is for heat pumps only and does not apply to solar. ECO4 covers insulation and heating, not solar. Some councils run local group buying schemes called Solar Together — worth checking by postcode.',

  finance: 'Solarify offers 0 percent interest finance plans through our finance partners. You can spread the cost of your solar system over 12 to 60 months with no interest charges. The monthly payment depends on the system size and term chosen. Finance eligibility is subject to credit check. Details are provided as part of the survey quote so you can compare cash purchase versus finance side by side.',

